import {
  Component,
  h,
  Prop,
  EventEmitter,
  Event,
  Watch,
  State,
  ComponentInterface,
  Host,
  Element,
} from '@stencil/core';
import { ks } from '@fe-infra/keystone-design-tokens';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { createOpenCloseMotion } from '@src/shared/animation';
import { sendActionTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { GlobalAlertVariant } from './types';
import {
  KsIconClose,
  KsIconFilledCaution,
  KsIconFilledInfo,
  KsIconFilledWarning,
} from '@fe-infra/keystone-icons-stencil';

const prefix = 'global-alert';

/**
 * @slot default - Main alert content rendered in the global alert body.
 * @slot title - Slot for the title of the global alert. Displayed above the main content.
 * @slot content - Slot for additional descriptive content. Displayed below the default slot content if both are used, or as the main content if the default slot is empty.
 * @slot actions - Slot for content appended to the right of the main body, often used for actions or links.
 * @slot icon - Slot for a custom icon. If not provided, a default icon based on the `variant` prop is displayed if `showIcon` is true.
 * @slot closeIcon - Slot for a custom close icon. If not provided, a default close icon is displayed if `closeable` is true.
 * @part base - The base container of the component.
 * @part body - The body container.
 * @part title - The title element.
 * @part content - The content container.
 */
@Component({
  tag: 'ks-global-alert',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsGlobalAlert implements ComponentInterface {
  @Element() el!: HTMLKsGlobalAlertElement;
  /** The visual variant of the global alert. Possible values include `"info"`, `"warning"`, and `"error"`. */
  @Prop() variant: GlobalAlertVariant = 'info';
  /** Indicates whether the global alert is currently open. When `true`, the alert is displayed. */
  @Prop() open?: boolean;
  /** Indicates whether the global alert is open by default. */
  @Prop() defaultOpen = true;
  /** Indicates whether to show an icon in the global alert. When `true`, an icon is displayed. */
  @Prop() showIcon = true;
  /** Indicates whether the global alert shows a close button. When `true`, a close button is displayed. */
  @Prop() closeable = true;
  /** Whether to enable animation when the global alert opens or closes. */
  @Prop() animation = true;
  /** Callback triggered after the global alert has closed. */
  @Prop() afterClose?: () => void;
  /** Custom event triggered when the global alert is closed. */
  @Event({ bubbles: false, composed: false }) ksClose!: EventEmitter<void>;

  @Slot({ slotname: 'title' }) private titleSlot?: Slots;
  @Slot({ slotname: 'actions' }) private actionsSlot?: Slots;

  @Uncontrollable('open', 'defaultOpen', null) @State() private mergedOpen?: boolean;
  /** 控制动画显隐 */
  @State() _open: boolean = this.mergedOpen ?? this.defaultOpen;

  private openAnimation = createOpenCloseMotion();

  @State() size = 16;

  private defaultContentSlotEl?: HTMLSlotElement;

  private namedContentSlotEl?: HTMLSlotElement;

  private getContentTooltip = () => {
    const nodes = [this.defaultContentSlotEl, this.namedContentSlotEl].flatMap(
      (slot) => slot?.assignedNodes({ flatten: true }) ?? [],
    );

    return nodes
      .map((node) => node.textContent ?? '')
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();
  };

  private renderIcon() {
    switch (this.variant) {
      case 'info':
        return <KsIconFilledInfo size={this.size} innerColor={ks.color.neutral.onFillLow} />;
      case 'warning':
        return <KsIconFilledWarning size={this.size} innerColor={ks.color.warning.onFillLow} />;
      case 'error':
        return <KsIconFilledCaution size={this.size} innerColor={ks.color.error.onFillLow} />;
      default:
        return null;
    }
  }

  @Watch('mergedOpen')
  async handleWatch(mergedOpen: boolean) {
    if (!this.animation) {
      this.openAnimation.cancel();
      this._open = mergedOpen;
      return;
    }

    await this.openAnimation.fade(this.el, mergedOpen, {
      duration: 200,
      beforeOpen: () => (this._open = true),
      afterOpen: () => sendExposeTracking(this.el, { eventType: 'visible' }),
      afterClose: () => {
        this._open = false;
        this.afterClose?.();
      },
    });
  }

  constructor() {
    registerPluginManager(this.el);
  }

  componentWillLoad() {
    this._open = this.mergedOpen ?? this.defaultOpen;
  }

  disconnectedCallback() {
    this.openAnimation.dispose();
  }

  private handleClose = () => {
    this.mergedOpen = false;
    this.ksClose.emit();
    sendActionTracking(this.el, { eventType: 'close' });
  };

  render() {
    const cls = {
      [prefix]: true,
      [`${prefix}--horizontal`]: true,
      [`${prefix}--${this.variant}`]: true,
    };
    return (
      <Host class="KsGlobalAlert" role="alert" hidden={!this._open}>
        {this._open ? (
          <div class={cls} part="base">
            <slot name="_internal-pagination"></slot>
            {this.showIcon && <slot name="icon">{this.renderIcon()}</slot>}
            <div class={`${prefix}__body`} part="body">
              {this.titleSlot && (
                <div class={`${prefix}__body-title`} part="title">
                  <slot name="title"></slot>
                </div>
              )}

              <div class={`${prefix}__body-content`} part="content">
                <ks-text
                  class={`${prefix}__body-content-text`}
                  variant="labelSm"
                  ellipsis={{ tooltip: this.getContentTooltip }}
                >
                  <slot ref={(el) => (this.defaultContentSlotEl = el as HTMLSlotElement)}></slot>{' '}
                  <slot name="content" ref={(el) => (this.namedContentSlotEl = el as HTMLSlotElement)}></slot>
                </ks-text>
              </div>
              <div class={`${prefix}__body-actions`}>{this.actionsSlot && <slot name="actions" />}</div>
            </div>
            {this.closeable && (
              <div class={`${prefix}__close`} onClick={this.handleClose} data-testid="ks-global-alert-index-8kHUB3">
                <ks-icon-button variant="text" size="xs">
                  <slot name="closeIcon">
                    <KsIconClose size="14" />
                  </slot>
                </ks-icon-button>
              </div>
            )}
          </div>
        ) : null}
      </Host>
    );
  }
}
